) VALUES (
    'val-di-fiemme-venue-guide',
    '{"en": "Val di Fiemme: Italy''s Cross-Country Capital", "de": "Val di Fiemme: Italiens Langlauf-Hauptstadt", "fr": "Val di Fiemme : La capitale italienne du ski de fond", "it": "Val di Fiemme: La capitale italiana dello sci di fondo", "es": "Val di Fiemme: La capital italiana del esquí de fondo", "pt": "Val di Fiemme: A capital italiana do esqui cross-country", "nl": "Val di Fiemme: Italië''s langlauf hoofdstad", "ar": "فال دي فييمي: عاصمة التزلج الريفي الإيطالية", "ja": "ヴァル・ディ・フィエンメ：イタリアのクロスカントリー首都", "zh": "Val di Fiemme: Yidali de Yueye Huaxue Shoudu", "ko": "발 디 피에메: 이탈리아의 크로스컨트리 수도"}'::jsonb,
    '{"en": "This Trentino valley has hosted multiple Nordic World Championships. The excellent trails and facilities make it a premier destination for cross-country skiing events.", "de": "Dieses Trentiner Tal hat mehrere Nordische Weltmeisterschaften ausgerichtet.", "fr": "Cette vallée du Trentin a accueilli plusieurs Championnats du monde nordiques.", "it": "Questa valle trentina ha ospitato molteplici Campionati mondiali nordici.", "es": "Este valle del Trentino ha albergado múltiples Campeonatos mundiales nórdicos.", "pt": "Este vale do Trentino sediou múltiplos Campeonatos mundiais nórdicos.", "nl": "Deze Trentino vallei heeft meerdere Noordse Wereldkampioenschappen georganiseerd.", "ar": "استضاف هذا الوادي في ترينتينو بطولات عالم نوردية متعددة", "ja": "このトレンティーノの谷は、複数のノルディック世界選手権を開催してきました。", "zh": "Zhe ge Teluntinuo shangu yi juxing duo jie Beiou Shijie Jinbiaosai.", "ko": "이 트렌티노 계곡은 여러 노르딕 세계 선수권 대회를 개최했습니다."}'::jsonb,
    '{"en": "<p>Val di Fiemme has established itself as one of the most important <a href=\"/cross-country-skiing-guide/\">cross-country skiing</a> venues in the world. This Italian valley in Trentino has hosted multiple Nordic World Championships and continues to welcome World Cup racing.</p><h2>Championship Heritage</h2><p>The valley has hosted several Nordic World Ski Championships, putting Italian cross-country skiing on the global map. These major events have left a legacy of world-class facilities and organizational expertise.</p><p>The combination of elevation, reliable snow, and infrastructure makes Val di Fiemme ideal for international competition.</p><h2>The Trails</h2><p>The cross-country trails wind through the beautiful Fiemme Valley, offering varied terrain suitable for all race formats. Challenging climbs alternate with technical descents, testing athletes'' complete skill sets.</p><p>Athletes like <a href=\"/therese-johaug-profile/\">Therese Johaug</a>, <a href=\"/jessie-diggins-profile/\">Jessie Diggins</a>, and <a href=\"/frida-karlsson-profile/\">Frida Karlsson</a> have raced on these world-class trails.</p><h2>Connected Venues</h2><p>Val di Fiemme connects seamlessly with <a href=\"/predazzo-venue-guide/\">Predazzo</a> for ski jumping events, creating a complete Nordic skiing destination. Athletes and fans can experience both disciplines in one stunning alpine valley.</p><h2>Tour de Ski</h2><p>The valley often hosts stages of the Tour de Ski, the grueling multi-day event that ranks among cross-country skiing''s most prestigious competitions.</p><h2>Location</h2><p>Val di Fiemme is in the Trentino region of northern Italy, about 50 km northeast of Trento. The scenic valley offers traditional Italian mountain hospitality.</p><h2>Getting There</h2><p>The venue is accessible from Innsbruck Airport (Austria) or from Verona and Venice airports in Italy. Train connections to Trento followed by bus service provide an alternative.</p>", "de": "<p>Val di Fiemme hat sich als einer der wichtigsten <a href=\"/cross-country-skiing-guide/\">Langlauf</a>-Austragungsorte der Welt etabliert. Dieses italienische Tal in Trentino hat mehrere Nordische Ski-Weltmeisterschaften ausgerichtet.</p><h2>Meisterschafts-Erbe</h2><p>Das Tal hat mehrere Nordische Ski-Weltmeisterschaften ausgerichtet.</p><h2>Die Loipen</h2><p>Athleten wie <a href=\"/therese-johaug-profile/\">Therese Johaug</a> und <a href=\"/jessie-diggins-profile/\">Jessie Diggins</a> sind auf diesen erstklassigen Loipen gelaufen.</p><h2>Verbundene Austragungsorte</h2><p>Val di Fiemme verbindet sich nahtlos mit <a href=\"/predazzo-venue-guide/\">Predazzo</a> für Skisprung-Events.</p>", "fr": "<p>Val di Fiemme s''est établi comme l''un des sites de <a href=\"/cross-country-skiing-guide/\">ski de fond</a> les plus importants au monde. Cette vallée italienne du Trentin a accueilli plusieurs Championnats du monde de ski nordique.</p><h2>Patrimoine des championnats</h2><p>La vallée a accueilli plusieurs Championnats du monde de ski nordique.</p><h2>Les pistes</h2><p>Des athlètes comme <a href=\"/therese-johaug-profile/\">Therese Johaug</a> et <a href=\"/jessie-diggins-profile/\">Jessie Diggins</a> ont couru sur ces pistes de classe mondiale.</p><h2>Sites connectés</h2><p>Val di Fiemme se connecte parfaitement à <a href=\"/predazzo-venue-guide/\">Predazzo</a> pour les épreuves de saut à ski.</p>", "it": "<p>La Val di Fiemme si è affermata come una delle sedi di <a href=\"/cross-country-skiing-guide/\">sci di fondo</a> più importanti al mondo. Questa valle italiana in Trentino ha ospitato molteplici Campionati mondiali di sci nordico.</p><h2>Patrimonio dei campionati</h2><p>La valle ha ospitato diversi Campionati mondiali di sci nordico.</p><h2>Le piste</h2><p>Atleti come <a href=\"/therese-johaug-profile/\">Therese Johaug</a> e <a href=\"/jessie-diggins-profile/\">Jessie Diggins</a> hanno gareggiato su queste piste di classe mondiale.</p><h2>Sedi collegate</h2><p>La Val di Fiemme si collega perfettamente a <a href=\"/predazzo-venue-guide/\">Predazzo</a> per gli eventi di salto con gli sci.</p>", "es": "<p>Val di Fiemme se ha establecido como uno de los lugares de <a href=\"/cross-country-skiing-guide/\">esquí de fondo</a> más importantes del mundo. Este valle italiano en Trentino ha albergado múltiples Campeonatos mundiales de esquí nórdico.</p><h2>Patrimonio de campeonatos</h2><p>El valle ha albergado varios Campeonatos mundiales de esquí nórdico.</p>", "pt": "<p>Val di Fiemme estabeleceu-se como um dos locais de <a href=\"/cross-country-skiing-guide/\">esqui cross-country</a> mais importantes do mundo. Este vale italiano em Trentino sediou múltiplos Campeonatos mundiais de esqui nórdico.</p><h2>Patrimônio de campeonatos</h2><p>O vale sediou vários Campeonatos mundiais de esqui nórdico.</p>", "nl": "<p>Val di Fiemme heeft zich gevestigd als een van de belangrijkste <a href=\"/cross-country-skiing-guide/\">langlauf</a> locaties ter wereld. Deze Italiaanse vallei in Trentino heeft meerdere Noordse Ski Wereldkampioenschappen georganiseerd.</p><h2>Kampioenschap erfgoed</h2><p>De vallei heeft meerdere Noordse Ski Wereldkampioenschappen georganiseerd.</p>", "ar": "<p>أثبتت فال دي فييمي نفسها كواحدة من أهم مواقع <a href=\"/cross-country-skiing-guide/\">التزلج الريفي</a> في العالم. استضاف هذا الوادي الإيطالي في ترينتينو بطولات عالم متعددة للتزلج الشمالي.</p><h2>تراث البطولات</h2><p>استضاف الوادي عدة بطولات عالم للتزلج الشمالي.</p>", "ja": "<p>ヴァル・ディ・フィエンメは、世界で最も重要な<a href=\"/cross-country-skiing-guide/\">クロスカントリースキー</a>会場の一つとして確立されています。トレンティーノにあるこのイタリアの谷は、複数のノルディック世界スキー選手権を開催してきました。</p><h2>選手権の遺産</h2><p>この谷は複数のノルディック世界スキー選手権を開催してきました。</p>", "zh": "<p>Val di Fiemme yi chengwei shijie shang zui zhongyao de <a href=\"/cross-country-skiing-guide/\">yueye huaxue</a> changguan zhiyi. Zhe ge weiyue Teluntinuo de Yidali shangu yi juxing duo jie Beiou Shijie Huaxue Jinbiaosai.</p><h2>Jinbiaosai yichan</h2><p>Zhe ge shangu yi juxing duo jie Beiou Shijie Huaxue Jinbiaosai.</p>", "ko": "<p>발 디 피에메는 세계에서 가장 중요한 <a href=\"/cross-country-skiing-guide/\">크로스컨트리 스키</a> 경기장 중 하나로 자리잡았습니다. 트렌티노에 위치한 이 이탈리아 계곡은 여러 노르딕 세계 스키 선수권 대회를 개최해 왔습니다.</p><h2>챔피언십 유산</h2><p>이 계곡은 여러 노르딕 세계 스키 선수권 대회를 개최해 왔습니다.</p>"}'::jsonb,
    'venue-guide',
    'XC',
    '{"en": "Val di Fiemme venue guide - Italian cross-country skiing capital in Trentino, host of multiple Nordic World Championships with world-class trails.", "de": "Val di Fiemme Venue Guide - Italiens Langlauf-Hauptstadt in Trentino.", "fr": "Guide du site de Val di Fiemme - Capitale italienne du ski de fond au Trentin.", "it": "Guida alla sede di Val di Fiemme - Capitale italiana dello sci di fondo in Trentino.", "es": "Guía del lugar de Val di Fiemme - Capital italiana del esquí de fondo en Trentino.", "pt": "Guia do local de Val di Fiemme - Capital italiana do esqui cross-country em Trentino.", "nl": "Val di Fiemme locatiegids - Italië''s langlauf hoofdstad in Trentino.", "ar": "دليل موقع فال دي فييمي - عاصمة التزلج الريفي الإيطالية في ترينتينو", "ja": "ヴァル・ディ・フィエンメ会場ガイド - トレンティーノにあるイタリアのクロスカントリースキー首都", "zh": "Val di Fiemme changguan zhinan - Teluntinuo de Yidali yueye huaxue shoudu", "ko": "발 디 피에메 경기장 가이드 - 트렌티노에 있는 이탈리아의 크로스컨트리 스키 수도"}'::jsonb,
